values (
  1,
  $q$FreightLoop$q$,
  $q$FreightLoop is a B2B SaaS platform that gives logistics operators one live view of shipments, fleet and warehouse operations. It combines real-time shipment tracking, automated proof-of-delivery, route and load optimisation, and carrier performance analytics. Operators use it to cut late deliveries, reduce empty miles, and replace spreadsheets, phone calls and WhatsApp groups with a single dashboard. It integrates with existing ERPs, GPS/telematics providers and transport management systems through APIs.$q$,
  'B2B logistics SaaS', $q$B2B SaaS, annual contracts priced per vehicle / per shipment tier$q$, 'Seed',
  $q$India (operations), selling to India + Southeast Asia first$q$,
  $q$Mid-size 3PLs, regional trucking fleet operators (50-500 vehicles), and manufacturers / FMCG distributors who run their own secondary freight$q$,
  $q$Raising a Seed round to expand sales and build the carrier-network and API-integration layer. Round size not specified in this sample.$q$,
  ARRAY['logistics','supply chain','freight','trucking','fleet management','warehouse','last-mile delivery','3PL','shipment tracking','route optimization','transportation management system','TMS','telematics','proof of delivery','carrier network','B2B SaaS','vertical SaaS','enterprise software','supply chain visibility','freight marketplace']::text[]
) on conflict (id) do nothing;

